package com.steven.assets.service.srpp.report;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.steven.assets.service.srpp.decision.*;
import com.steven.assets.service.srpp.decision.DecisionInputCapturePort.Frozen;
import com.steven.assets.srpp.*;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;

public final class SrppReportFixtures {
    public static final LocalDate DATE=LocalDate.parse("2026-10-08");
    public static final Instant AT=Instant.parse("2026-10-08T01:05:00Z");
    public static final String SWAGGER="b".repeat(64);
    public static final ObjectMapper MAPPER=new ObjectMapper().registerModule(new JavaTimeModule()).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    public static final SrppReportAuthority AUTHORITY=new SrppReportAuthority(new DecisionPolicyAuthority());
    public static SupportedPolicy supported(){var doc=SrppPolicyDocument.parse(SrppJcs.canonicalize(SrppReportModuleCalculator.registryDocument(AUTHORITY.model())));return new SupportedPolicy(AUTHORITY.decision().policy().bundleHash(),SrppFormulaCatalog.FORMULA_VERSION_V2,SrppJcs.hash(doc.document()),SrppFormulaCatalog.formulaSetSha256(SrppFormulaCatalog.FORMULA_VERSION_V2),doc.document(),SrppJcs.parseStrict(SrppFormulaCatalog.manifestJcs(SrppFormulaCatalog.FORMULA_VERSION_V2)),doc.targets(),AT);}
    public static Map<String,ObjectNode> states(long owner,String slot){Map<String,ObjectNode> out=new LinkedHashMap<>();var port=new UnavailableSrppReportConsumerState();for(String c:List.of("Codex","Claude"))out.put(c,port.read(owner,c,DATE,slot));return out;}
    public static ObjectNode reportReservations(long owner){ObjectNode source=JsonNodeFactory.instance.objectNode().put("ownerUserId",owner).put("tradingDate",DATE.toString()).put("policyBundleSha256",supported().bundleHash()).put("status","VERIFIED").put("verified",true).put("coverage","COMPLETE");source.putArray("rows");return source;}
    public static ObjectNode extras(){ObjectNode extras=JsonNodeFactory.instance.objectNode();ObjectNode symbols=extras.putObject("symbols");Set<String> codes=new TreeSet<>(List.of("00713","0056","00878","00919","00865B","00719B","00697B","VOO","009826","VT","SGOV","GOOGL"));AUTHORITY.model().path("detailed_target_allocation_2027").fieldNames().forEachRemaining(code->{if(!Set.of("TWD_term_deposits","demand_deposits_and_cash").contains(code))codes.add(code);});for(String key:List.of("short_term_opportunity_d171","bond_short_term_opportunity_d187"))AUTHORITY.model().path("execution_policy").path(key).path("symbols").forEach(code->codes.add(code.asText()));for(String code:codes){String market=code.matches("[A-Z.]+")?"美股":"台股";ObjectNode body=JsonNodeFactory.instance.objectNode().put("status","UNAVAILABLE");body.put("symbol",code);body.put("market",market);symbols.set(market+":"+code,body);extras.set("market:"+market+":"+code,body);}for(String k:List.of("tax","payroll","regime","global-pace","short-sleeve","us-tactical","dca-identity"))extras.putObject(k).put("status","UNAVAILABLE");ObjectNode pending=extras.putObject("topup-state");pending.put("status","VERIFIED").put("verified",true).put("ownerUserId",7).put("tradingDate",DATE.toString()).put("policyBundleSha256",AUTHORITY.decision().policy().bundleHash()).put("coverage","COMPLETE");pending.putObject("pending").put("verified",true).put("coverage","COMPLETE").putArray("orders");return extras;}
    public static Frozen qualified(String slot,Instant at,boolean pendingVerified)throws Exception{
        var fixture=SrppReportModuleCalculatorTest.fixture();ObjectNode input=fixture.frozen().input();input.put("schemaVersion",1);input.put("tradingDate",DATE.toString());input.put("slot",slot);input.put("capturedAt",at.toString());ObjectNode source=input.withObject("sources");((ObjectNode)source.path("assets")).put("generatedAt",at.toString());source.set("policy",frozen(7,at,slot,"fixture").input().path("sources").path("policy"));source.set("report-reservations",reportReservations(7));source.putObject("swagger").put("sha256",SWAGGER);extras().fields().forEachRemaining(e->source.set(e.getKey(),e.getValue()));
        ObjectNode facts=(ObjectNode)SrppReportModuleCalculator.normalize(MAPPER.valueToTree(fixture.frozen().facts()));facts.put("slot",slot);facts.put("capturedAt",at.toString());facts.path("symbols").forEach(s->{((ObjectNode)s.path("quote")).put("updatedAt",at.toString());((ObjectNode)s.path("book")).put("sourceTime",at.toString()).put("fetchedAt",at.toString());if(!pendingVerified)((ObjectNode)s.path("pending")).put("status","UNAVAILABLE").put("reason","PENDING_ORDERS_UNAVAILABLE");});input.set("facts",facts);
        ObjectNode vector=JsonNodeFactory.instance.objectNode();source.fields().forEachRemaining(e->{ObjectNode v=vector.putObject(e.getKey());v.put("sourceId",e.getKey());v.put("revision",pendingVerified?"qualified-pending":"pending-unavailable");v.put("capturedAt",at.toString());v.put("sha256",SrppJcs.hash(e.getValue()));v.put("coverage","COMPLETE");v.put("validation","VERIFIED");});return new Frozen(MAPPER.convertValue(facts,DecisionFacts.Input.class),input,vector,1,at.toString());
    }
    public static Frozen frozen(long owner,Instant at,String slot,String revision){
        var p=AUTHORITY.decision().policy();var unavailable=new DecisionFacts.Evidence("UNAVAILABLE","CANONICAL_SOURCE_UNAVAILABLE");
        var facts=new DecisionFacts.Input(DATE,slot,at,List.of(),new BigDecimal("100000"),new BigDecimal("100000"),BigDecimal.ZERO,BigDecimal.ZERO,null,unavailable,unavailable,Map.of(),new DecisionFacts.Budget(0,0,0,false,BigDecimal.ZERO,Map.of(),BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO),unavailable,null);
        ObjectNode input=JsonNodeFactory.instance.objectNode();input.put("schemaVersion",1);input.put("ownerUserId",owner);input.put("tradingDate",DATE.toString());input.put("slot",slot);input.put("capturedAt",at.toString());input.set("facts",SrppReportModuleCalculator.normalize(MAPPER.valueToTree(facts)));ObjectNode sources=input.putObject("sources");
        ObjectNode assets=sources.putObject("assets");assets.put("generatedAt",at.toString());ObjectNode snapshot=assets.putObject("snapshot"),live=assets.putObject("liveAssets");snapshot.put("id",9);snapshot.put("snapshotDate",DATE.toString());live.put("snapshotId",9);live.put("snapshotDate",DATE.toString());snapshot.putArray("stocks");snapshot.putArray("funds");live.putArray("stocks");snapshot.put("totalDeposit","100000");snapshot.put("totalFundValue","0");snapshot.put("totalStockValue","0");snapshot.put("totalAssets","100000");live.put("totalDeposit","100000");live.put("totalFundValue","0");live.put("liveStockValue","0");live.put("liveTotalAssets","100000");ObjectNode deposit=snapshot.putArray("deposits").addObject();deposit.put("id",1);deposit.put("bankId",1);deposit.put("currency","TWD");deposit.put("depositType","SAVINGS");deposit.put("amount","100000");deposit.put("originalAmount","100000");deposit.putNull("estimatedAnnualInterest");
        sources.putObject("policy").put("rawModelBytes",AUTHORITY.decision().modelBytes()).put("rawManifestBytes",AUTHORITY.decision().manifestBytes()).put("bundleHash",p.bundleHash());sources.set("report-reservations",reportReservations(owner));sources.putArray("reservations");sources.putArray("ledger");sources.putObject("calendar").put("tw",true);sources.putObject("swagger").put("sha256",SWAGGER);sources.putObject("classifications").putObject("resolvedStockClasses");for(String key:List.of("fx","bear-window","subaccounts"))sources.putObject(key).put("status","UNAVAILABLE");for(String code:p.symbols())for(String prefix:List.of("quote","book","radar","daily","dividends","pending","tradability","minute"))sources.putObject(prefix+":"+code).put("status","UNAVAILABLE");
        extras().fields().forEachRemaining(e->sources.set(e.getKey(),e.getValue()));ObjectNode vector=JsonNodeFactory.instance.objectNode();sources.fields().forEachRemaining(e->{ObjectNode v=vector.putObject(e.getKey());v.put("sourceId",e.getKey());v.put("revision",revision);v.put("capturedAt",at.toString());v.put("sha256",SrppJcs.hash(e.getValue()));v.put("coverage","COMPLETE");v.put("validation","VERIFIED");});return new Frozen(facts,input,vector,9,at.toString());
    }
}
